import{_ as a,c as t,o as i,a5 as n}from"./chunks/framework.CUJoMJm2.js";const u=JSON.parse('{"title":"Why Sideband?","description":"","frontmatter":{},"headers":[],"relativePath":"why-sideband.md","filePath":"why-sideband.md","lastUpdated":0}'),s={name:"why-sideband.md"};function o(r,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="why-sideband" tabindex="-1">Why Sideband? <a class="header-anchor" href="#why-sideband" aria-label="Permalink to “Why Sideband?”">​</a></h1><p>Building browser ↔ local daemon communication is harder than it looks. What starts as &quot;just WebSockets&quot; becomes a months-long detour through reconnection state machines, NAT traversal, and TLS certificate management.</p><p>Sideband handles the hard parts so you can focus on your app.</p><p><strong>Sideband in one sentence:</strong></p><blockquote><p>Browser ↔ local daemon communication — without WebSocket code.</p></blockquote><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to “The Problem”">​</a></h2><p>You have a local daemon (AI agent, dev tool, background service) and need a browser UI. Sounds simple:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Browser → WebSocket → localhost:3000 → Daemon</span></span></code></pre></div><p>Then users arrive.</p><ul><li>First, reconnect bugs you cannot reproduce</li><li>Then NATs and corporate firewalls</li><li>Then HTTPS + localhost certificate hacks</li><li>Then security reviews flag DNS rebinding</li><li>Then support tickets say &quot;it just hangs&quot;</li></ul><p>Each issue is solvable. Together, they turn networking into your product.</p><h2 id="why-this-keeps-happening" tabindex="-1">Why This Keeps Happening <a class="header-anchor" href="#why-this-keeps-happening" aria-label="Permalink to “Why This Keeps Happening”">​</a></h2><p>Browser ↔ daemon networking combines every hard thing at once: TCP state across sleep/wake, user networks you do not control, and security constraints around localhost. By the time it works for real users, you have rebuilt a small transport stack.</p><h2 id="common-alternatives-and-their-limits" tabindex="-1">Common Alternatives (and Their Limits) <a class="header-anchor" href="#common-alternatives-and-their-limits" aria-label="Permalink to “Common Alternatives (and Their Limits)”">​</a></h2><h3 id="diy-websockets" tabindex="-1">DIY WebSockets <a class="header-anchor" href="#diy-websockets" aria-label="Permalink to “DIY WebSockets”">​</a></h3><ul><li>Reconnect logic is a state machine, not a retry loop</li><li>Mixed-content and CORS lead to self-signed cert management</li><li>Every release risks regression in edge cases</li></ul><p><strong>Why Sideband wins:</strong> Delete your WebSocket code. Reconnects, multiplexing, and correlation are handled.</p><h3 id="ngrok-cloudflare-quick-tunnels" tabindex="-1">ngrok / Cloudflare Quick Tunnels <a class="header-anchor" href="#ngrok-cloudflare-quick-tunnels" aria-label="Permalink to “ngrok / Cloudflare Quick Tunnels”">​</a></h3><ul><li>ngrok injects an interstitial page that breaks API clients</li><li>Cloudflare Quick Tunnels have no SSE support and aggressive phishing detection</li><li>TLS terminates at their edge, so they can inspect traffic</li></ul><p><strong>Why Sideband wins:</strong> End-to-end encryption by default. No interstitials, no PKI ceremony.</p><h3 id="tailscale-mesh-vpns" tabindex="-1">Tailscale / Mesh VPNs <a class="header-anchor" href="#tailscale-mesh-vpns" aria-label="Permalink to “Tailscale / Mesh VPNs”">​</a></h3><ul><li>Requires VPN client install for every user</li><li>Funnel needs account setup, ACL config, and port restrictions (443/8443/10000)</li><li>Bundling <code>tsnet</code> bloats binary size and memory</li></ul><p><strong>Why Sideband wins:</strong> Browser-to-daemon access without VPN clients or admin console configuration.</p><h3 id="webrtc-datachannels" tabindex="-1">WebRTC DataChannels <a class="header-anchor" href="#webrtc-datachannels" aria-label="Permalink to “WebRTC DataChannels”">​</a></h3><ul><li>You still need a signaling channel (usually WebSockets)</li><li>Hole-punching fails on symmetric NATs; TURN becomes mandatory</li><li>Mobile carriers aggressively timeout UDP mappings</li></ul><p><strong>Why Sideband wins:</strong> Predictable relay-based sessions without signaling servers or TURN.</p><h3 id="firebase-supabase-realtime" tabindex="-1">Firebase / Supabase Realtime <a class="header-anchor" href="#firebase-supabase-realtime" aria-label="Permalink to “Firebase / Supabase Realtime”">​</a></h3><ul><li>Broadcast is at-most-once (lossy); Postgres Changes hammers WAL</li><li>Fan-out billing: 1 message to 100 subscribers = 101 billable messages</li><li>Not designed for local daemon patterns</li></ul><p><strong>Why Sideband wins:</strong> Local-first RPC without cloud gravity or write amplification.</p><h2 id="what-sideband-does" tabindex="-1">What Sideband Does <a class="header-anchor" href="#what-sideband-does" aria-label="Permalink to “What Sideband Does”">​</a></h2><p>Sideband replaces your browser ↔ daemon networking layer.</p><p>You do not manage:</p><ul><li>WebSocket lifecycles and reconnection state</li><li>TLS certificates for localhost</li><li>NAT traversal or port forwarding</li><li>Multi-client coordination</li><li>Request/response correlation</li></ul><p>You get a single abstraction that works across networks and devices.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Benefit</th></tr></thead><tbody><tr><td>E2EE by default</td><td>Relay cannot decrypt your payloads</td></tr><tr><td>NAT traversal</td><td>Works behind firewalls without port forwarding</td></tr><tr><td>Automatic reconnection</td><td>Handles network changes, sleep/wake, flaky connections</td></tr><tr><td>Multiplexed streams</td><td>Multiple concurrent requests over one connection</td></tr><tr><td>Typed RPC</td><td>Request/response correlation with TypeScript types</td></tr></tbody></table><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h2><p>Sideband is a layered stack (<a href="/protocols/">protocols</a>) with two session modes:</p><ul><li><strong>SBRP (relay-based)</strong> — available today; secure sessions with end-to-end encryption</li><li><strong>SBDP (direct/P2P)</strong> — specified and planned for when peers can connect directly</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────┐         ┌─────────┐         ┌─────────┐</span></span>
<span class="line"><span>│ Browser │◄─TLS───►│  Relay  │◄─TLS───►│ Daemon  │</span></span>
<span class="line"><span>└─────────┘         └─────────┘         └─────────┘</span></span>
<span class="line"><span>     │                   │                   │</span></span>
<span class="line"><span>     └────────── E2EE encrypted ─────────────┘</span></span></code></pre></div><p>The relay validates tokens, routes connections, and sees metadata (timing/size), but cannot decrypt payloads. Endpoints authenticate daemons via Ed25519 signatures and establish session keys with X25519 + ChaCha20-Poly1305 (TOFU pinning on first connection).</p><h2 id="when-teams-switch-to-sideband" tabindex="-1">When Teams Switch to Sideband <a class="header-anchor" href="#when-teams-switch-to-sideband" aria-label="Permalink to “When Teams Switch to Sideband”">​</a></h2><ul><li>Localhost-only is blocking growth or demos</li><li>Users want remote access from another device</li><li>Reconnect bugs keep resurfacing</li><li>Security reviews flag local endpoints</li><li>You are tired of debugging networking instead of your product</li></ul><p>If any of these sound familiar, you are past the point where DIY is cheap.</p><h2 id="when-sideband-is-not-a-fit" tabindex="-1">When Sideband Is Not a Fit <a class="header-anchor" href="#when-sideband-is-not-a-fit" aria-label="Permalink to “When Sideband Is Not a Fit”">​</a></h2><ul><li>Cloud-native SaaS (you already have backend infra)</li><li>Apps without a browser component</li><li>Compliance-first environments (early-stage)</li></ul><h2 id="get-started" tabindex="-1">Get Started <a class="header-anchor" href="#get-started" aria-label="Permalink to “Get Started”">​</a></h2><p>See the <a href="/guide/">Getting Started</a> guide to add Sideband to your project.</p>`,47)])])}const b=a(s,[["render",o]]);export{u as __pageData,b as default};
